function getDocsInFolder(folderId) {
  const folder = DriveApp.getFolderById(folderId);
  const files = folder.getFilesByType(MimeType.GOOGLE_DOCS);
  let docs = [];

  while (files.hasNext()) {
    const file = files.next();
    const doc = DocumentApp.openById(file.getId());
    docs.push(doc);
  }

  return docs;
}

function generateEmbeddings(text) {
  const apiKey= 'sk-Suv5GmCJSGDVP-tR8BynIKeHV07VLwEmn_3TEFo-krT3BlbkFJS0dnHX8XMjkrG9hkh-BvtUaOtz_K3vLj0X2AA2ZJwA'; // Replace with your OpenAI API key !!!
  const url = 'https://api.openai.com/v1/embeddings';

  const data = {
    model: "text-embedding-ada-002", // Use the appropriate model for embeddings
    input: text
  };

  const options = {
    method: 'post',
    contentType: 'application/json',
    headers: {
      'Authorization': 'Bearer ' + apiKey
    },
    payload: JSON.stringify(data)
  };

  try {
    const response = UrlFetchApp.fetch(url, options);
    const json = JSON.parse(response.getContentText());
    return json.data[0].embedding;
  } catch (e) {
    Logger.log('Error: ' + e.toString());
    return null;
  }
}

function generateAndStoreEmbeddings(folderId, sheetId, sheetName) {
  const docs = getDocsInFolder(folderId);
  const sheet = SpreadsheetApp.openById(sheetId).getSheetByName(sheetName);
  sheet.clear(); // Clear previous data

  docs.forEach(doc => {
    const body = doc.getBody().getText();
    const paragraphs = body.split('\n');

    paragraphs.forEach(paragraph => {
      if (paragraph.trim()) { // Skip empty paragraphs
        const embedding = generateEmbeddings(paragraph);
        if (embedding) {
          // Store the paragraph and its embedding in the sheet
          sheet.appendRow([paragraph, JSON.stringify(embedding)]);
        }
      }
    });
  });
}

